⊢ ∀n a.
    shift_right a n =
    if n = 0 then a
    else if a = 0w ∨ n > dimindex (:α) then 0w
    else if n > 32 then shift_right (a ⋙ 32) (n − 32)
    else if n > 16 then shift_right (a ⋙ 16) (n − 16)
    else if n > 8 then shift_right (a ⋙ 8) (n − 8)
    else shift_right (a ⋙ 1) (n − 1)

⊢ ∀n a.
    shift_left a n =
    if n = 0 then a
    else if a = 0w ∨ n > dimindex (:α) then 0w
    else if n > 32 then shift_left (a ≪ 32) (n − 32)
    else if n > 16 then shift_left (a ≪ 16) (n − 16)
    else if n > 8 then shift_left (a ≪ 8) (n − 8)
    else shift_left (a ≪ 1) (n − 1)

⊢ ∀n a.
    arith_shift_right a n =
    if n = 0 then a
    else if a = 0w ∨ n > dimindex (:α) ∧ ¬word_msb a then 0w
    else if a = -1w ∨ n > dimindex (:α) ∧ word_msb a then -1w
    else if n > 32 then arith_shift_right (a ≫ 32) (n − 32)
    else if n > 16 then arith_shift_right (a ≫ 16) (n − 16)
    else if n > 8 then arith_shift_right (a ≫ 8) (n − 8)
    else arith_shift_right (a ≫ 1) (n − 1)

⊢ ∀w n.
    any_word64_ror w n =
    if 64 ≤ n then any_word64_ror w (n − 64)
    else if 32 ≤ n then any_word64_ror (w ⇄ 32) (n − 32)
    else if 16 ≤ n then any_word64_ror (w ⇄ 16) (n − 16)
    else if 8 ≤ n then any_word64_ror (w ⇄ 8) (n − 8)
    else if 4 ≤ n then any_word64_ror (w ⇄ 4) (n − 4)
    else if 2 ≤ n then any_word64_ror (w ⇄ 2) (n − 2)
    else if 1 ≤ n then w ⇄ 1
    else w

