⊢ (∀v0 d. skip_comment "" d v0 = NONE) ∧ (∀x v1 d. skip_comment (STRING x "") d v1 = NONE) ∧
  ∀y xs x loc d.
    skip_comment (STRING x (STRING y xs)) d loc =
    if STRING x (STRING y "") = "(*" then skip_comment xs (d + 1) (next_loc 2 loc)
    else if STRING x (STRING y "") = "*)" then
      if d = 0 then SOME (xs,next_loc 2 loc) else skip_comment xs (d − 1) (next_loc 2 loc)
    else if ORD x = 10 then skip_comment (STRING y xs) d (next_line loc)
    else skip_comment (STRING y xs) d (next_loc 1 loc)

